export class ModalHistoryComprasCtrl{static $inject=["mainService","toastService","$uibModalInstance","params"];constructor(t,i,e,s){this._mS=t,this._tS=i,this.$uibModalInstance=e,this._params=s,this.articleName=`${this._params.codigo} -> ${this._params.descripcion}`,this.historyComprasArticle=[]}$onInit(){this.getArticleHC()}getArticleHC(t){try{this._mS.getData("get","CompraHabitual/Get?json="+JSON.stringify({tipo:3,idArticulo:this._params.idArticulo}),null,!0).then((t=>{t.payload?(this.historyComprasArticle=JSON.parse(t.payload),this.articleName=this.historyComprasArticle[0].articulo):this._tS.toastr("warning","Este articulo aun no tiene registros de compra habitual")}))}catch(t){}}askToDeleteCH(t){Swal.fire({title:"¿Está seguro/a de desvincular este articulo de compras habituales?",text:"¡No podrás revertir esto!",icon:"warning",showCancelButton:!0,confirmButtonColor:"#3085d6",cancelButtonColor:"#d33",confirmButtonText:"Si!",cancelButtonText:"No",allowOutsideClick:!1}).then((i=>{i.isConfirmed&&this.deleteCH(t)}))}deleteCH=t=>{try{this._mS.getData("delete","CompraHabitual/Delete?id="+t.idCompraHabitual,null,!0).then((i=>{if("0"!=i.code){if("1"==i.code){let e=this.historyComprasArticle.indexOf(t);this.historyComprasArticle.splice(e,1),this._tS.toastr("success",i.message)}}else this._tS.toastr("warning",i.message)}),(t=>{}))}catch(t){}};closeModal(){this.$uibModalInstance.close()}}